functions.__pgn_annotation_nag_from_string:
pgn_annotation_t __pgn_annotation_nag_from_string(char *str, size_t *consumed)
{
    pgn_annotation_t annotation = PGN_ANNOTATION_UNKNOWN;
    size_t cursor = 0;
    if (str[cursor] != '$')
        return annotation;
    while (str[cursor] == '$')
    {
        ((((*__ctype_b_loc())[(int)((str[++cursor]))] & (unsigned short int)_ISdigit))
             ? (void)(0)
             : __assert_fail("isdigit(str[++cursor])", "annotation.c", 42, __extension__ __PRETTY_FUNCTION__));
        char *endptr = ((void *)0);
        long num = strtol(str + cursor, &endptr, 10);
        annotation = num;
        cursor += endptr - (str + cursor);
        pgn_cursor_skip_whitespace(str, &cursor);
    }
    pgn_cursor_revisit_whitespace(str, &cursor);
    *consumed += cursor;
    return annotation;
}

functions.__pgn_annotation_from_string:
pgn_annotation_t __pgn_annotation_from_string(char *str, size_t *consumed)
{
    pgn_annotation_t annotation = PGN_ANNOTATION_UNKNOWN;
    if (str[0] == '\0')
        return annotation;
    if (str[0] == '!')
    {
        (*consumed)++;
        annotation = PGN_ANNOTATION_GOOD_MOVE;
    }
    if (str[0] == '?')
    {
        (*consumed)++;
        annotation = PGN_ANNOTATION_MISTAKE;
    }
    if (str[1] == '\0')
        return annotation;
    if (str[0] == '!' && str[1] == '!')
    {
        (*consumed)++;
        annotation = PGN_ANNOTATION_BRILLIANT_MOVE;
    }
    if (str[0] == '!' && str[1] == '?')
    {
        (*consumed)++;
        annotation = PGN_ANNOTATION_INTRESTING_MOVE;
    }
    if (str[0] == '?' && str[1] == '!')
    {
        (*consumed)++;
        annotation = PGN_ANNOTATION_DUBIOUS_MOVE;
    }
    if (str[0] == '?' && str[1] == '?')
    {
        (*consumed)++;
        annotation = PGN_ANNOTATION_BLUNDER;
    }
    return annotation;
}

functions.pgn_annotation_to_string:
size_t pgn_annotation_to_string(pgn_annotation_t annotation, char *dest)
{
    switch (annotation)
    {
    case PGN_ANNOTATION_UNKNOWN:
        return 0;
    case PGN_ANNOTATION_NULL:
        break;
    case PGN_ANNOTATION_GOOD_MOVE:
        strcpy(dest, "!");
        return 1;
    case PGN_ANNOTATION_MISTAKE:
        strcpy(dest, "?");
        return 1;
    case PGN_ANNOTATION_BRILLIANT_MOVE:
        strcpy(dest, "!!");
        return 2;
    case PGN_ANNOTATION_BLUNDER:
        strcpy(dest, "??");
        return 2;
    case PGN_ANNOTATION_INTRESTING_MOVE:
        strcpy(dest, "!?");
        return 2;
    case PGN_ANNOTATION_DUBIOUS_MOVE:
        strcpy(dest, "?!");
        return 2;
    }
    int bytes = sprintf(dest, "$%d", annotation);
    ((bytes >= 0) ? (void)(0) : __assert_fail("bytes >= 0", "annotation.c", 137, __extension__ __PRETTY_FUNCTION__));
    return bytes;
}

enums.pgn_score_single_t:
typedef enum pgn_score_single_t
{
    ZERO = 0,
    ONE,
    HALF,
} pgn_score_single_t;

functions.__pgn_score_single_from_string:
pgn_score_single_t __pgn_score_single_from_string(char *str, size_t *consumed)
{
    if (strncmp(str, "1/2", 3) == 0)
    {
        *consumed += 3;
        return HALF;
    }
    else if (*str == '0')
    {
        *consumed += 1;
        return ZERO;
    }
    else if (*str == '1')
    {
        *consumed += 1;
        return ONE;
    }
    return -1;
}

functions.__pgn_score_from_string:
pgn_score_t __pgn_score_from_string(char *str, size_t *consumed)
{
    size_t cursor = 0;
    if (str[cursor] == '*')
    {
        cursor++;
        *consumed += cursor;
        return PGN_SCORE_ONGOING;
    }
    pgn_score_single_t white = __pgn_score_single_from_string(str + cursor, &cursor);
    if ((int)white == -1)
        return PGN_SCORE_UNKNOWN;
    if (str[cursor++] != '-')
        return PGN_SCORE_UNKNOWN;
    pgn_score_single_t black = __pgn_score_single_from_string(str + cursor, &cursor);
    if ((int)black == -1)
        return PGN_SCORE_UNKNOWN;
    *consumed += cursor;
    if (white == HALF && black == HALF)
        return PGN_SCORE_DRAW;
    else if (white == 1 && black == 0)
        return PGN_SCORE_WHITE_WON;
    else if (white == 0 && black == 1)
        return PGN_SCORE_BLACK_WON;
    else if (white == 0 && black == 0)
        return PGN_SCORE_FORFEIT;
    else if (white == 0 && black == HALF)
        return PGN_SCORE_WHITE_FORFEIT;
    else if (white == HALF && black == 0)
        return PGN_SCORE_BLACK_FORFEIT;
    else
        return PGN_SCORE_UNKNOWN;
}

functions.pgn_score_to_string:
char *pgn_score_to_string(pgn_score_t score)
{
    switch (score)
    {
    case PGN_SCORE_UNKNOWN:
        break;
    case PGN_SCORE_ONGOING:
        return "*";
    case PGN_SCORE_DRAW:
        return "1/2-1/2";
    case PGN_SCORE_WHITE_WON:
        return "1-0";
    case PGN_SCORE_BLACK_WON:
        return "0-1";
    case PGN_SCORE_FORFEIT:
        return "0-0";
    case PGN_SCORE_WHITE_FORFEIT:
        return "0-1/2";
    case PGN_SCORE_BLACK_FORFEIT:
        return "1/2-0";
    }
    return "";
}

