                 ? (void)(0)
                 : __assert_fail("str[++cursor] == 'O'", "moves.c", 49, __extension__ __PRETTY_FUNCTION__));
            move.castles = 3;
            cursor++;
        }
        goto check;
    }
    move.piece = pgn_piece_from_char(str[cursor++]);
    if (move.piece == PGN_PIECE_UNKNOWN)
    {
        move.piece = PGN_PIECE_PAWN;
        cursor--;
