    cursor += move.captures;
    if (((*__ctype_b_loc())[(int)((str[cursor]))] & (unsigned short int)_ISlower))
    {
        ((((*__ctype_b_loc())[(int)((str[cursor]))] & (unsigned short int)_ISlower))
             ? (void)(0)
             : __assert_fail("islower(str[cursor])", "moves.c", 72, __extension__ __PRETTY_FUNCTION__));
        move.dest.file = str[cursor++];
        ((((*__ctype_b_loc())[(int)((str[cursor]))] & (unsigned short int)_ISdigit))
             ? (void)(0)
             : __assert_fail("isdigit(str[cursor])", "moves.c", 74, __extension__ __PRETTY_FUNCTION__));
        move.dest.rank = str[cursor++] - '0';
    }
    else
    {
        move.dest = move.from;
        move.from = (pgn_coordinate_t){0};
    }
    move.promoted_to = pgn_piece_from_char(str[cursor]);
    if (move.promoted_to == PGN_PIECE_UNKNOWN)
    {
        switch (str[cursor])
        {
        case '(':
            move.promoted_to = pgn_piece_from_char(str[++cursor]);
            ((move.promoted_to != PGN_PIECE_UNKNOWN) ? (void)(0)
                                                     : __assert_fail("move.promoted_to != PGN_PIECE_UNKNOWN", "moves.c",
                                                                     86, __extension__ __PRETTY_FUNCTION__));
            ((str[++cursor] == ')')
                 ? (void)(0)
                 : __assert_fail("str[++cursor] == ')'", "moves.c", 87, __extension__ __PRETTY_FUNCTION__));
            cursor++;
            break;
        case '=':
        case '/':
            move.promoted_to = pgn_piece_from_char(str[++cursor]);
            ((move.promoted_to != PGN_PIECE_UNKNOWN) ? (void)(0)
                                                     : __assert_fail("move.promoted_to != PGN_PIECE_UNKNOWN", "moves.c",
                                                                     93, __extension__ __PRETTY_FUNCTION__));
            cursor++;
            break;
        }
    }
    ((move.dest.file != 0) ? (void)(0)
                           : __assert_fail("move.dest.file != 0", "moves.c", 99, __extension__ __PRETTY_FUNCTION__));
    ((move.dest.rank != 0) ? (void)(0)
                           : __assert_fail("move.dest.rank != 0", "moves.c", 100, __extension__ __PRETTY_FUNCTION__));
