    move.check = __pgn_check_from_string(str + cursor, &cursor);
    move.annotation = __pgn_annotation_from_string(str + cursor, &cursor);
    _Bool skipped_whitespace_before_ep = pgn_cursor_skip_whitespace(str, &cursor);
    if (str[cursor] == 'e' && str[cursor + 1] == '.')
    {
        ((skipped_whitespace_before_ep)
             ? (void)(0)
             : __assert_fail("skipped_whitespace_before_ep", "moves.c", 112, __extension__ __PRETTY_FUNCTION__));
        ((str[cursor] == 'e') ? (void)(0)
                              : __assert_fail("str[cursor] == 'e'", "moves.c", 114, __extension__ __PRETTY_FUNCTION__));
        ((str[++cursor] == '.')
             ? (void)(0)
             : __assert_fail("str[++cursor] == '.'", "moves.c", 115, __extension__ __PRETTY_FUNCTION__));
        ((str[++cursor] == 'p')
             ? (void)(0)
             : __assert_fail("str[++cursor] == 'p'", "moves.c", 116, __extension__ __PRETTY_FUNCTION__));
        ((str[++cursor] == '.')
             ? (void)(0)
             : __assert_fail("str[++cursor] == '.'", "moves.c", 117, __extension__ __PRETTY_FUNCTION__));
        cursor++;
        move.en_passant = 1;
    }
    _Bool skipped_whitespace_after_ep =
        move.en_passant ? pgn_cursor_skip_whitespace(str, &cursor) : skipped_whitespace_before_ep;
    if (move.annotation == PGN_ANNOTATION_UNKNOWN)
    {
        move.annotation = __pgn_annotation_nag_from_string(str + cursor, &cursor);
        if (move.annotation != PGN_ANNOTATION_UNKNOWN)
        {
            ((skipped_whitespace_after_ep)
                 ? (void)(0)
                 : __assert_fail("skipped_whitespace_after_ep", "moves.c", 132, __extension__ __PRETTY_FUNCTION__));
        }
