functions.pgn_move_to_string:
size_t pgn_move_to_string(pgn_move_t *move, char *dest)
{
    size_t cursor = 0;
    switch (move->castles)
    {
    case 0:
        break;
    case 2:
        strcpy(dest, "O-O");
        cursor += 2 * 2 - 1;
        goto check;
    case 3:
        strcpy(dest, "O-O-O");
        cursor += 3 * 2 - 1;
        goto check;
    }
    ((move->piece != PGN_PIECE_UNKNOWN)
         ? (void)(0)
         : __assert_fail("move->piece != PGN_PIECE_UNKNOWN", "moves.c", 167, __extension__ __PRETTY_FUNCTION__));
    if (move->piece != PGN_PIECE_PAWN)
    {
        dest[cursor++] = move->piece;
    }
    if (move->from.file)
        dest[cursor++] = move->from.file;
    if (move->from.rank)
        dest[cursor++] = '0' + move->from.rank;
    if (move->captures)
        dest[cursor++] = 'x';
    dest[cursor++] = move->dest.file;
    dest[cursor++] = '0' + move->dest.rank;
    if (move->promoted_to)
    {
        ((move->piece == PGN_PIECE_PAWN)
             ? (void)(0)
             : __assert_fail("move->piece == PGN_PIECE_PAWN", "moves.c", 181, __extension__ __PRETTY_FUNCTION__));
        ((move->promoted_to != PGN_PIECE_PAWN)
             ? (void)(0)
             : __assert_fail("move->promoted_to != PGN_PIECE_PAWN", "moves.c", 182, __extension__ __PRETTY_FUNCTION__));
        dest[cursor++] = '=';
        dest[cursor++] = move->promoted_to;
    }
check:
    switch (move->check)
    {
    case PGN_CHECK_NONE:
        break;
    case PGN_CHECK_MATE:
        dest[cursor++] = '#';
        break;
    case PGN_CHECK_SINGLE:
        dest[cursor++] = '+';
        break;
    case PGN_CHECK_DOUBLE:
        dest[cursor++] = '+';
        dest[cursor++] = '+';
        break;
    }
    if (move->annotation >= PGN_ANNOTATION_GOOD_MOVE && move->annotation <= PGN_ANNOTATION_DUBIOUS_MOVE)
    {
        cursor += pgn_annotation_to_string(move->annotation, dest + cursor);
    }
    if (move->en_passant)
    {
        dest[cursor++] = ' ';
        strcpy(dest + cursor, "e.p.");
        cursor += 4;
    }
    if (move->annotation > PGN_ANNOTATION_DUBIOUS_MOVE || move->annotation == PGN_ANNOTATION_NULL)
    {
        dest[cursor++] = ' ';
        cursor += pgn_annotation_to_string(move->annotation, dest + cursor);
    }
    dest[cursor] = '\0';
    return cursor;
}

