functions.pgn_alternative_moves_poll:
size_t pgn_alternative_moves_poll(pgn_alternative_moves_t **alt, pgn_comments_t **placeholder, char *str, int expect)
{
    size_t cursor = 0;
    while (str[cursor] == '(')
    {
        cursor++;
        if (!*alt)
            *alt = pgn_alternative_moves_init();
        pgn_cursor_skip_whitespace(str, &cursor);
        pgn_alternative_moves_push(*alt,
                                   __pgn_moves_from_string_recurse(str + cursor, &cursor, pgn_moves_init(), expect));
        pgn_cursor_skip_whitespace(str, &cursor);
        ((str[cursor++] == ')')
             ? (void)(0)
             : __assert_fail("str[cursor++] == ')'", "moves.c", 371, __extension__ __PRETTY_FUNCTION__));
        pgn_cursor_skip_whitespace(str, &cursor);
        cursor += pgn_comments_poll(placeholder, PGN_COMMENT_POSITION_AFTER_ALTERNATIVE, str + cursor);
    }
    return cursor;
}

