functions.pgn_comments_poll:
size_t pgn_comments_poll(pgn_comments_t **comments, pgn_comment_position_t pos, char *str)
{
    size_t cursor = 0;
    if (str[cursor] == '{')
    {
        if (!*comments)
            *comments = pgn_comments_init();
        while (str[cursor] == '{')
        {
            pgn_comment_t comment = __pgn_comment_from_string(str + cursor, &cursor);
            comment.position = pos;
            pgn_comments_push(*comments, comment);
            pgn_cursor_skip_whitespace(str, &cursor);
        }
        ((str[cursor] != '{')
             ? (void)(0)
             : __assert_fail("str[cursor] != '{'", "comments.c", 110, __extension__ __PRETTY_FUNCTION__));
        ((str[cursor] != '}')
             ? (void)(0)
             : __assert_fail("str[cursor] != '}'", "comments.c", 111, __extension__ __PRETTY_FUNCTION__));
        pgn_cursor_skip_whitespace(str, &cursor);
    }
    return cursor;
}

